// tank top (masked shell over the torso)
const NT=0.34,FB=2.27,BB=1.3,NW=1.65;
function tankMask(th,y,R){
  if(y>NT+1e-4)return false;
  const co=Math.cos(th),x=Math.abs(R*Math.sin(th));
  const t=(NT-y)/(co>=0?FB:BB);
  if(t<1&&x<NW*Math.sqrt(1-t*t))return false;
  const a=Math.acos(Math.max(-1,Math.min(1,co)))*180/Math.PI;
  const da=(a-92)/16,dy=(y+0.5)/0.6;
  if(da*da+dy*dy<1)return false;
  return true;
}
const tank=new THREE.Group();tank.name='tank-top';torso.add(tank);
const tankMesh=new THREE.Mesh(surf(-3.2,NT,150,288,1.015,tankMask,null),tankMat);
tankMesh.name='tank-cloth';tank.add(tankMesh);

