const TS=1.03;
function sp(x,y,sd){
  const R=prof(y)*TS;const xx=Math.max(-R,Math.min(R,x));
  return new THREE.Vector3(xx,y,sd*SZ*Math.sqrt(Math.max(0,R*R-xx*xx)));
}
function tube(pts,rad,segs,closed){
  const cv=new THREE.CatmullRomCurve3(pts,closed,'centripetal');
  return new THREE.Mesh(new THREE.TubeGeometry(cv,segs,rad,6,closed),trimMat);
}
