// eyes
function makeEye(sg,name){
  const e=new THREE.Group();e.name=name;
  const y=1.22,x=0.87*sg,R=prof(y);
  const z=SZ*Math.sqrt(Math.max(0,R*R-x*x));
  e.position.set(x*0.985,y,z-0.03);
  e.rotation.order='YXZ';e.rotation.set(-0.12,0.35*sg,0);
  const lid=sph(0.33,lidMat);lid.scale.set(1,1,0.5);lid.name=name+'-lid';e.add(lid);
  const ball=sph(0.265,irisMat);ball.scale.set(1,1,0.72);ball.position.z=0.08;ball.name=name+'-ball';e.add(ball);
  const pg=new THREE.Group();pg.name=name+'-pupil';pg.position.z=0.255;e.add(pg);
  const pu=sph(0.11,pupilMat);pu.scale.set(1.2,0.82,0.3);pg.add(pu);
  const hl=sph(0.03,whiteMat);hl.position.set(-0.08,0.09,0.245);hl.name=name+'-glint';e.add(hl);
  return e;
}
const eyes=new THREE.Group();eyes.name='eyes';headIn.add(eyes);
eyes.add(makeEye(1,'eye-left'));
eyes.add(makeEye(-1,'eye-right'));

