function makeLeg(sg,sd){
  const l=new THREE.Group();l.name='leg-'+sd;l.position.set(sg*0.95,-3.5,0);
  l.add(cap(ZERO,new THREE.Vector3(sg*0.05,-1.2,0.05),0.62,skinMat));
